      }],
      verDetalle: 0,
      valida: 0,
      validaMensaje: [],
      adModal: 0,
      adAccion: 0,
      adNombre: '',
      adId: ''
    };
  },
  computed: {
    calcularTotal: function calcularTotal() {
      var resultado = 0.0;

      for (var i = 0; i < this.detalles.length; i++) {
        resultado = resultado + (this.detalles[i].cantidad * this.detalles[i].precio - this.detalles[i].descuento);
      }

      return resultado;
    }
  },
  watch: {
    dialog: function dialog(val) {
      val || this.close();
    }
  },
  created: function created() {
    this.listar();
    this.selectPersona();
    this.selectEstado();
    this.selectNivel(); //  this.capturarcodigo();
    // this.listarArticulos()
  },
  methods: {
    selectPersona: function selectPersona() {
      var me = this;
      var personaArray = [];
      var header = {
        "auth-token": this.$store.state.token
      };
      var configuracion = {
        headers: header
      };
      axios.get('clientes/', configuracion).then(function (response) {
        personaArray = response.data;
        personaArray.map(function (x) {
          me.clientes.push({
            text: x.CodigoCliente + " " + x.RazonSocial,
            value: x.CodigoCliente
          });
        });
      }).catch(function (error) {
        console.log(error);
      });
    },
    selectEstado: function selectEstado() {
      var me = this;
      var personaArray = [];
      var header = {
        "auth-token": this.$store.state.token
      };
      var configuracion = {
        headers: header
      };
      axios.get('estadorecepciones/', configuracion).then(function (response) {
        personaArray = response.data;
        personaArray.map(function (x) {
          me.estadorecepciones.push({
            text: x.codigo + " " + x.descripcion,
            value: x.codigo
          });
        });
      }).catch(function (error) {
        console.log(error);
      });
    },
    capturarcodigo: function capturarcodigo(texto) {
      var cod = texto.split(' ')[0];
      return cod;
    },
    selectNivel: function selectNivel() {
      var me = this;
      var personaArray = [];
      var header = {
        "auth-token": this.$store.state.token
      };
      var configuracion = {
        headers: header
      };
      axios.get('nivelcombustibles/', configuracion).then(function (response) {
        personaArray = response.data;
        personaArray.map(function (x) {
          me.nivelcombustibles.push({
            text: x.codigo + " " + x.descripcion,
            value: x.codigo
          });
        });
      }).catch(function (error) {
        console.log(error);
      });
    },
    buscarCodigo: function buscarCodigo() {
      var me = this; // let header={"auth-token" : this.$store.state.token};
      // let configuracion= {headers : header};

      var header = {
        "auth-token": this.$store.state.token
      };
      var configuracion = {
        headers: header
      };
      var cliente = this.cliente;
      console.log(cliente);
      axios.get('rvehiculo/' + cliente, configuracion).then(function (response) {
        console.log(response.data); //   me.agregarDetalle(response.data);
      }).catch(function (error) {
        me.errorArticulo = 'No existe el artículo.';
      });
    },
    // se agrega el datalle a la tabla
    agregarDetalle: function agregarDetalle(data) {
      this.errorArticulo = null;

      if (this.encuentra(data.chapa) == true) {
        this.errorArticulo = 'El vehiculo ya ha sido agregado.';
      } else {
        console.log(data.chapa);
        this.Codigo = data.codigo;
        this.chapa = data.chapa;
      }

      this.close();
    },
    agregarTabla: function agregarTabla() {
      var codigonivel = this.capturarcodigo(this.nivelcombustible);
      this.detalles.push({
        Codigo: this.Codigo,
        chapa: this.chapa,
        km: this.km,
        nivelcombustible: this.nivelcombustible,
        codigonivel: codigonivel // chapa:this.chapa,

      });
    },
    encuentra: function encuentra(chapa) {
      var sw = 0;

      for (var i = 0; i < this.detalles.length; i++) {
        if (this.detalles[i].chapa == chapa) {
          sw = true;
        }
      }

      return sw;
    },
    eliminarDetalle: function eliminarDetalle(arr, item) {
      var i = arr.indexOf(item);

      if (i != -1) {
        arr.splice(i, 1);
      }
    },
    listarArticulos: function listarArticulos() {
      var me = this;
      var header = {
        "auth-token": this.$store.state.token
      };
      var configuracion = {
        headers: header
      };
      var cliente = this.cliente;
      axios.get('rvehiculo/' + cliente, configuracion).then(function (response) {
        me.articulos = response.data;
      }).catch(function (error) {
        console.log(error);
      });
    },
    mostrarModalArticulos: function mostrarModalArticulos() {
      this.dialog = 1;
      this.listarArticulos();
    },
    listarDetalles: function listarDetalles() {
      console.log("cliente 2");
      var me = this;
      var header = {
        "auth-token": this.$store.state.token
      };
      var configuracion = {
        headers: header
      };
      console.log("hola");

      cliente: this.cliente;

      console.log(cliente);
      axios.get('rvehiculo/' + cliente, configuracion).then(function (response) {
        me.detalles = response.data.detalles;
      }).catch(function (error) {
        console.log(error);
      });
    },
    verIngreso: function verIngreso(item) {
      console.log("cliente3");
      this.limpiar();
      this.tipo_comprobante = item.tipo_comprobante;
      this.serie_comprobante = item.serie_comprobante;
      this.num_comprobante = item.num_comprobante;
      this.persona = item.persona._id;
      this.impuesto = item.impuesto;
      this.listarDetalles();
      this.verNuevo = 1;
      this.verDetalle = 1;
    },
    listar: function listar() {
      var me = this;
      var header = {
        "auth-token": this.$store.state.token
      };
      var configuracion = {
        headers: header
      };
      axios.get('rvehiculo/', configuracion).then(function (response) {
        me.ventas = response.data;
        console.log(me.ventas);
      }).catch(function (error) {
        console.log(error);
      });
    },
    listarUno: function listarUno(item) {
      var me = this;
      var header = {
        "auth-token": this.$store.state.token
      };
      var configuracion = {
        headers: header
      };
      axios.get('rvehiculo/update/' + item.numero, configuracion).then(function (response) {
        me.detalles = response.data;

        for (var i in me.detalles) {
          me.chapa = me.detalles[i].chapa;
          me.cliente = me.detalles[i].RazonSocial;
          me.Codigo = me.detalles[i].codigo;
          me.detalles[i].Codigo = me.detalles[i].codigo;
          me.estadorecepcion = me.detalles[i].estadorecepcion;
          me.nivelcombustible = me.detalles[i].nivel;
          me.detalles[i].nivelcombustible = me.detalles[i].nivel;
          me.km = me.detalles[i].km;
          me.detalles[i].codigonivel = me.detalles[i].codigonivelcombustible;
          me.observacion = me.detalles[i].observaciones; // console.log(me.cliente)
        }

        me.mostrarNuevo();
      }).catch(function (error) {
        console.log(error);
      });
    },
    limpiar: function limpiar() {
      this.Codigo = '';
      this.observacion = '';
      this.cliente = '';
      this.nivelcombustible = '';
      this.estadorecepcion = '';
      this.chapa = '';
      this.km = '';
      this.detalles = [];
      this.validaMensaje = [];
      this.verDetalle = 0;
    },
    validar: function validar() {
      this.valida = 0;
      this.validaMensaje = [];

      if (!this.persona) {
        this.validaMensaje.push('Seleccione un cliente.');
      }

      if (!this.tipo_comprobante) {
        this.validaMensaje.push('Seleccione un tipo de comprobante.');
      }

      if (!this.num_comprobante) {
        this.validaMensaje.push('Ingrese el número del comprobante.');
      }

      if (!this.impuesto || this.impuesto < 0 || this.impuesto > 1) {
        this.validaMensaje.push('Ingrese un impuesto válido.');
      }

      if (this.detalles.length <= 0) {
        this.validaMensaje.push('Ingrese al menos un artículo al detalle');
      }

      if (this.validaMensaje.length) {
        this.valida = 1;
      }

      return this.valida;
    },
    mostrarNuevo: function mostrarNuevo() {
      this.verNuevo = 1;
    },
    ocultarNuevo: function ocultarNuevo() {
      this.verNuevo = 0;
      this.limpiar();
    },
    guardar: function guardar() {
      var me = this;
      var header = {
        "auth-token": this.$store.state.token
      };
      var configuracion = {
        headers: header
      };
      console.log(this.$store.state.usuario);
      axios.post('rvehiculo/', {
        'CodigoSucursal': this.$store.state.usuario.CodigoSucursal,
        'PuntoExpedicion': this.$store.state.usuario.PuntoExpedicion,
        'recibidopor': this.$store.state.usuario.codigo,
        'codigocliente': this.capturarcodigo(this.cliente),
        'estado': this.capturarcodigo(this.estadorecepcion),
        'observaciones': this.observacion,
        'detalles': this.detalles
      }, configuracion).then(function (response) {
        me.dialogoConfirmacion = true;
        me.limpiar();
        me.close();
        me.listar();
        me.ocultarNuevo();
      }).catch(function (error) {
        console.log(error);
      });
    },
    activarDesactivarMostrar: function activarDesactivarMostrar(accion, item) {
      this.adModal = 1;
      this.adNombre = item.num_comprobante;
      this.adId = item._id;

      if (accion == 1) {
        this.adAccion = 1;
      } else if (accion == 2) {
        this.adAccion = 2;
      } else {
        this.adModal = 0;
      }
    },
    activarDesactivarCerrar: function activarDesactivarCerrar() {
      this.adModal = 0;
    },
    activar: function activar() {
      var me = this;
      var header = {
        "Token": this.$store.state.token
      };
      var configuracion = {
        headers: header
      };
      axios.put('venta/activate', {
        '_id': this.adId
      }, configuracion).then(function (response) {
        me.adModal = 0;
        me.adAccion = 0;
        me.adNombre = '';
        me.adId = '';
        me.listar();
      }).catch(function (error) {
        console.log(error);
      });
    },
    desactivar: function desactivar() {
      var me = this;
      var header = {
        "Token": this.$store.state.token
      };
      var configuracion = {
        headers: header
      };
      axios.put('venta/deactivate', {
        '_id': this.adId
      }, configuracion).then(function (response) {
        me.adModal = 0;
        me.adAccion = 0;
        me.adNombre = '';
        me.adId = '';
        me.listar();
      }).catch(function (error) {
        console.log(error);
      });
    },
    close: function close() {
      this.dialog = false;
    }
  }
};
